import {stepPack,packLayout} from './pack-engine.js';
import {createQuickGame,snapshotQuick,restoreQuick,QUICK_MODES} from './pack-checkpoint.js';
import {storyJournal} from './story-journal.js';
import {createStory} from './living-story.js';
import {worldLook} from './world.js';
import {ROOMS,ITEMS,ENDINGS} from './story-engine.js';
import {PackRenderer} from './pack-renderer.js';
const $=id=>document.getElementById(id);
export const PACK_MODES=['flappy','cross','snake','runner','story'];
const INFO={runner:{title:'DAWG Dash',tag:'THE NIGHT HAS THREE LANES.',desc:'Sprint through the city. Change lanes, jump crates, slide under arches, and collect gold. Every obstacle row leaves a clear lane.',hint:'Swipe / arrows / WASD · Up or Space jumps · Down slides',goal:'1 point per meter · +25 per gold · shields & magnets',button:'RUN THE NIGHT',targets:[400,1200,2500]},snake:{title:'Neon Snake',tag:'CHASE THE GOLD. WATCH YOUR TAIL.',desc:'Guide your growing neon pack through the grid. Collect gold, plan your turns, and leave yourself a way out.',hint:'Swipe or use arrows · WASD / arrow keys',goal:'25 points per gold · growing tail · rising speed',button:'START THE CHASE',targets:[100,300,600]},flappy:{title:'Flappy DAWG',tag:'BIG EYES. NO FLIGHT LICENSE.',desc:'Tap to keep DAWG airborne. Slip through neon towers, find your rhythm, and land perfect-center bonuses.',hint:'Tap the sky or FLAP · Space / ↑',goal:'10 points per gate · +5 for a perfect center',button:'TAKE FLIGHT',targets:[50,150,300]},cross:{title:'DAWG Cross',tag:'WHY DID THE DAWG CROSS?',desc:'Dodge late-night traffic, ride floating decks, and pocket gold on the way uptown. Every block is a new gamble.',hint:'Swipe or use arrows · WASD / arrow keys',goal:'10 per new row · +25 gold coins · keep moving',button:'HIT THE STREET',targets:[100,300,600]}};
export class ArcadePack {
 constructor(face,io){this.io=io;this.kind=null;this.session=false;this.games={};const savedRuns=io.read('packRuns',{});for(const kind of QUICK_MODES){const restored=restoreQuick(savedRuns?.[kind]);if(restored)this.games[kind]=restored;}this.lastSave=0;this.recorded=new WeakSet();this.game=null;this.last=0;this.lastHud=0;this.countdown=0;this.scroll=0;this.renderer=new PackRenderer($('packCanvas'),face);this.storyRenderer=new PackRenderer($('storyCanvas'),face);this.story=createStory(io.read('story',null));this.storyEnds=io.read('storyEndings',[]);if(!Array.isArray(this.storyEnds))this.storyEnds=[];this.storyEnds=this.storyEnds.filter(id=>Object.hasOwn(ENDINGS,id));this.storyEndRecorded=!!this.story.ending;face.addEventListener?.('load',()=>{if(this.kind==='story')this.renderStory();else if(QUICK_MODES.includes(this.kind)&&this.game)this.renderer.draw(this.game,this.kind,performance.now());});
  $('packStart').onclick=()=>this.play();$('packHome').onclick=()=>this.exit();$('packBack').onclick=()=>this.exit();$('packPause').onclick=()=>this.togglePause();$('packSound').onclick=()=>{io.soundToggle();this.syncSound();};$('packFlap').addEventListener('pointerdown',e=>{e.preventDefault();this.input('up');});$('packFlap').onclick=e=>{if(e.detail===0)this.input('up');};
  document.querySelectorAll('[data-pack-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();this.input(b.dataset.packDir);});b.onclick=e=>{if(e.detail===0)this.input(b.dataset.packDir);};});
  let pointer=null;const board=$('packCanvas');board.addEventListener('pointerdown',e=>{if(pointer)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};board.setPointerCapture(e.pointerId);if(this.kind==='flappy')this.input('up');});board.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId||!['cross','snake','runner'].includes(this.kind))return;const x=e.clientX-pointer.x,y=e.clientY-pointer.y;if(Math.max(Math.abs(x),Math.abs(y))<24)return;pointer.moved=true;this.input(Math.abs(x)>Math.abs(y)?x>0?'right':'left':y>0?'down':'up');pointer.x=e.clientX;pointer.y=e.clientY;});const release=e=>{if(pointer?.id!==e.pointerId)return;if(['cross','runner'].includes(this.kind)&&!pointer.moved)this.input('up');pointer=null;};board.addEventListener('pointerup',release);board.addEventListener('pointercancel',()=>pointer=null);board.addEventListener('lostpointercapture',()=>pointer=null);
  window.addEventListener('keydown',e=>{if(!this.session||document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey)return;const dirs={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'};if(e.key==='Escape'){e.preventDefault();this.exit();return;}if(e.key.toLowerCase()==='p'){e.preventDefault();if(!e.repeat)this.togglePause();return;}const dir=dirs[e.key]||dirs[e.key.toLowerCase()]||(e.code==='Space'?'up':null);if(dir&&e.target.tagName!=='BUTTON'){e.preventDefault();if(!e.repeat)this.input(dir);}});
  const resize=()=>{this.layout();};window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);window.addEventListener('pagehide',()=>this.saveRuns());window.addEventListener('orientationchange',()=>this.pause());window.addEventListener('blur',()=>this.pause());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.pause();});
  $('storyLocations').onclick=e=>{const b=e.target.closest('[data-room]');if(b){this.story.go(b.dataset.room);this.saveStory();this.renderStory();}};
  $('storyChoices').onclick=e=>{const b=e.target.closest('[data-choice]');if(b){this.story.choose(b.dataset.choice);this.storyChanged();}};
  $('storyInventory').onclick=e=>{const b=e.target.closest('[data-item]');if(b){this.story.use(b.dataset.item);this.storyChanged();}};
  $('storyFollow').onclick=()=>{const lead=storyJournal(this.story).lead;if(lead){if(lead.room===this.story.room)this.story.say(lead.text,'YOUR CASEBOOK');else this.story.go(lead.room);this.saveStory();this.renderStory();}};
  $('storyHint').onclick=()=>{this.story.say(this.story.hint(),'A NUDGE FROM THE NARRATOR');this.renderStory();};
  $('storyReset').onclick=()=>io.confirm('Another night?','Generate a new episode with a different cast, clues, scenery, and soundcheck. Your collected endings and arcade records stay saved.','NEW EPISODE ↗',()=>{this.story=createStory();this.storyRenderer.character=this.io.prepare?.('story',this.story,true);this.storyEndRecorded=false;this.saveStory();this.renderStory();});
 }
 select(kind){this.exit();this.kind=kind;this.last=0;this.countdown=0;$('packPanel').hidden=!QUICK_MODES.includes(kind);$('storyPanel').hidden=kind!=='story';if(kind==='story'){this.renderStory();return;}if(!INFO[kind])return;this.game=this.games[kind]??=createQuickGame(kind);this.renderer.character=this.io.prepare?.(kind,this.game);this.renderer.particles=[];$('dashGraphicsStatus').hidden=kind!=='runner';const info=INFO[kind];$('packTitle').textContent=info.title;$('packTag').textContent=info.tag;$('packDescription').textContent=info.desc;$('packHint').textContent=info.hint;$('packGoal').textContent=info.goal+' · WORLD '+worldLook(this.game.worldSeed).code;$('packFlap').hidden=kind!=='flappy';$('packDpad').hidden=kind==='flappy';$('packControlHint').textContent=kind==='runner'?'← → CHANGE LANES · ↑ JUMP · ↓ SLIDE':kind==='flappy'?'TAP ANYWHERE ON THE SKY':kind==='snake'?'SWIPE TO TURN · PLAN YOUR NEXT MOVE':'TAP TO HOP FORWARD · SWIPE TO STEER';$('packCanvas').setAttribute('aria-label',info.title+'. '+info.hint);document.querySelectorAll('[data-pack-dir]').forEach(b=>b.setAttribute('aria-label',kind==='runner'?({left:'Dodge left',right:'Dodge right',up:'Jump over crates',down:'Slide under arches'})[b.dataset.packDir]:'Move '+b.dataset.packDir));this.renderer.reduced=this.io.prefs.fx==='low'||window.matchMedia('(prefers-reduced-motion: reduce)').matches;this.sync();this.renderer.draw(this.game,kind,performance.now());}
 enter(){if(this.session)return;this.session=true;this.scroll=window.scrollY;document.body.classList.add('pack-session');document.documentElement.classList.add('pack-session');this.layout();$('packCanvas').focus({preventScroll:true});}
 exit(){this.pause();if(!this.session)return;this.session=false;document.body.classList.remove('pack-session','pack-landscape');document.documentElement.classList.remove('pack-session');window.scrollTo(0,this.scroll);$('packStart').focus({preventScroll:true});}
 layout(){if(!this.session)return;const v=window.visualViewport,width=v?.width||innerWidth,height=v?.height||innerHeight,cs=getComputedStyle($('safeAreaProbe'));const safe={top:parseFloat(cs.paddingTop)||0,bottom:parseFloat(cs.paddingBottom)||0,left:parseFloat(cs.paddingLeft)||0,right:parseFloat(cs.paddingRight)||0};const l=packLayout(width,height,safe);const panel=$('packPanel');for(const[k,val]of Object.entries({'--pack-width':width+'px','--pack-height':height+'px','--pack-left':(v?.offsetLeft||0)+'px','--pack-top':(v?.offsetTop||0)+'px','--pack-stage-width':l.stageWidth+'px'}))panel.style.setProperty(k,val);document.body.classList.toggle('pack-landscape',l.landscape);}
 play(){if(!INFO[this.kind]||document.querySelector('dialog[open]')||this.countdown)return;this.enter();if(this.game.status==='over'){this.game=createQuickGame(this.kind);this.games[this.kind]=this.game;this.renderer.particles=[];$('packGoal').textContent=INFO[this.kind].goal+' · WORLD '+worldLook(this.game.worldSeed).code;}if(this.game.status==='playing')return;this.renderer.character=this.io.prepare?.(this.kind,this.game,this.game.status==='ready');this.countdown=performance.now()+1500;this.sync();this.io.sound(440,.07);}
 pause(){if(!this.game)return;this.countdown=0;this.game.pause();this.saveRuns();this.sync();}
 togglePause(){if(this.countdown||this.game?.status==='playing')this.pause();else if(this.game?.status==='paused'||this.game?.status==='ready')this.play();}
 input(dir){if(!this.session||!this.game||this.countdown)return;if(['paused','ready'].includes(this.game.status)){this.play();return;}if(this.game.status!=='playing')return;if(this.kind==='flappy')this.game.flap();else this.game.move(dir);}
 syncSound(){$('packSound').textContent=this.io.soundOn()?'♫':'♪';$('packSound').setAttribute('aria-label',this.io.soundOn()?'Turn sound off':'Turn sound on');}
 sync(){if(!INFO[this.kind]||!this.game)return;const g=this.game,info=INFO[this.kind],best=this.io.best(this.kind);$('packScore').textContent=g.score.toLocaleString();$('packBest').textContent=best.toLocaleString();$('packPause').textContent=g.status==='paused'?'▷':'Ⅱ';$('packPause').setAttribute('aria-label',g.status==='paused'?'Resume game':'Pause game');$('packPause').disabled=g.status==='over';this.syncSound();$('packOverlay').hidden=g.status==='playing'||!!this.countdown;$('packCountdown').hidden=!this.countdown;$('packHome').hidden=!this.session;$('packResult').hidden=g.status!=='over';
  $('packOverlayTag').textContent=g.status==='paused'?'TAKE A BREATHER':g.status==='over'?'ANOTHER SHOT AT GREATNESS':info.tag;$('packOverlayTitle').textContent=g.status==='paused'?'PAWS FOR A SEC.':g.status==='over'?g.score+' POINTS':info.title;$('packOverlayText').textContent=g.status==='paused'?'Your run is paused. Ready when you are.':g.status==='over'?g.reason:info.desc;$('packStart').textContent=g.status==='paused'?'KEEP GOING ↗':g.status==='over'?'PLAY AGAIN ↗':info.button+' ↗';
  if(g.status==='over'){const medal=info.targets.filter(t=>g.score>=t).length,next=info.targets.find(t=>g.score<t);$('packResult').textContent=(g.score>0&&g.score===best?'PERSONAL BEST · ':'')+(['NEXT UP: BRONZE','BRONZE MEDAL','SILVER MEDAL','GOLD MEDAL'][medal])+(next?' · '+(next-g.score)+' TO '+next:'')+'\n'+(this.kind==='runner'?Math.floor(g.distance)+' METERS · '+g.coins+' GOLD · '+g.dodged+' DODGES':this.kind==='flappy'?g.gates+' GATES · '+g.perfect+' PERFECT':this.kind==='snake'?g.body.length+' LONG · '+g.coins+' GOLD':g.furthest+' ROWS · '+g.coins+' GOLD');}
 }
 frame(now){if(this.kind==='story'){if(!document.hidden&&!this.storyRenderer.reduced&&now-(this.lastStoryFrame||0)>83){this.storyRenderer.story(this.story,now);this.lastStoryFrame=now;}return;}if(!INFO[this.kind]||!this.game)return;const dt=this.last?(now-this.last)/1000:0;this.last=now;const g=this.game,prior=g.status;if(this.countdown){const left=this.countdown-now;if(left<=0){this.countdown=0;const fresh=g.status==='ready';g.start();if(this.kind==='flappy'&&fresh)g.flap();this.sync();}else $('packCountdown').textContent=Math.ceil(left/500);}else stepPack(g,dt);
  for(const e of g.events){this.renderer.event(e,g);if(e.type==='score'||e.type==='coin')this.io.sound(e.perfect?950:700,.09);else if(e.type==='power')this.io.sound(1000,.15,'triangle',.025);else if(e.type==='shield')this.io.sound(180,.12,'triangle',.02);else if(e.type==='flap')this.io.sound(350,.04,'sine',.012);else if(e.type==='over'){this.io.sound(150,.25);if(this.io.prefs.haptics&&typeof navigator.vibrate==='function'){try{navigator.vibrate(25);}catch{}}}}
  g.events=[];if(g.status==='over'&&!this.recorded.has(g)){this.recorded.add(g);this.io.record(this.kind,g.score,Math.min(250,Math.floor(g.score/3)));this.saveRuns();}if(prior!==g.status||g.status==='playing'&&now-this.lastHud>80){this.sync();this.lastHud=now;}if(g.status==='playing'||prior!==g.status||this.renderer.particles.length||this.countdown)this.renderer.draw(g,this.kind,now);if(g.status==='playing'&&now-this.lastSave>2000){this.saveRuns();this.lastSave=now;}
 }
 saveRuns(){const out={};for(const kind of QUICK_MODES){const snapshot=snapshotQuick(this.games[kind],kind);if(snapshot)out[kind]=snapshot;}this.io.write('packRuns',out);}
 saveStory(){this.io.write('story',this.story.save());}
 storyChanged(){const s=this.story;if(s.ending&&!this.storyEndRecorded){this.storyEndRecorded=true;const first=!this.storyEnds.includes(s.ending);if(first){this.storyEnds.push(s.ending);this.io.write('storyEndings',this.storyEnds);}this.io.record('story',s.result?.score??ENDINGS[s.ending].score,first?200:0);this.io.sound(760,.25);}else this.io.sound(430,.06);this.saveStory();this.renderStory();}
 renderStory(){this.storyRenderer.character=this.io.prepare?.('story',this.story);const s=this.story,journal=storyJournal(s);$('storyJournal').replaceChildren();for(const note of journal.notes){const row=document.createElement('div'),b=document.createElement('b'),p=document.createElement('p');row.className='journal-note';b.textContent=note.title;p.textContent=note.text;row.append(b,p);$('storyJournal').append(row);}$('storyLead').textContent=journal.lead?.text||'Case closed. Your next episode has new clues.';$('storyFollow').disabled=!journal.lead;$('storyFollow').textContent=journal.lead?.room===s.room?'REVIEW THIS LOCATION ↗':'FOLLOW THIS LEAD ↗';const room=s.roomInfo?.()||ROOMS[s.room];this.storyRenderer.reduced=this.io.prefs.fx==='low'||window.matchMedia('(prefers-reduced-motion: reduce)').matches;$('storyEpisode').textContent=s.episode?s.episode.plot.title+' · EPISODE '+s.episode.look.code:'Original chapter · A Very Important Pug';$('storySceneName').textContent=room.name;$('storyLabel').textContent=room.label;$('storySpeaker').textContent=s.speaker;$('storyDialogue').textContent=s.text;$('storyNotice').textContent=s.notice;$('storyNotice').hidden=!s.notice;$('storyEndingCount').textContent=this.storyEnds.length+' / 3 ENDINGS';this.storyRenderer.story(s,performance.now());
  $('storyLocations').replaceChildren();for(const [id,base]of Object.entries(ROOMS)){const r=s.roomInfo?.(id)||base;const b=document.createElement('button');b.dataset.room=id;b.textContent=(id==='roof'&&!s.flags.pass?'◇ ':'')+r.name;b.setAttribute('aria-pressed',String(id===s.room));b.disabled=!!s.ending;$('storyLocations').append(b);}
  $('storyInventory').replaceChildren();for(const id of s.inventory){const item=s.item?.(id)||ITEMS[id],b=document.createElement('button');b.dataset.item=id;b.title=item.description;b.disabled=!!s.ending;const i=document.createElement('b');i.textContent=item.icon;const name=document.createElement('span');name.textContent=item.name;b.append(i,name);$('storyInventory').append(b);}
  $('storyChoices').replaceChildren();for(const a of s.actions()){const b=document.createElement('button');b.dataset.choice=a.id;const title=document.createElement('strong'),detail=document.createElement('small');title.textContent=a.label;detail.textContent=a.detail;b.append(title,detail);$('storyChoices').append(b);}
  const tasks=[['Wake DJ '+(s.episode?.cast.dj||'Vinyl'),s.flags.awake],['Finish the demo',s.flags.mixed],['Earn a wristband',s.flags.pass],['Make your night',!!s.ending],...(s.episode?[['Bonus: return the badge',s.flags.favor]]:[])];$('storyQuests').replaceChildren();for(const [label,done]of tasks){const span=document.createElement('span');span.className=done?'done':'';span.textContent=(done?'✓ ':'○ ')+label;$('storyQuests').append(span);}
  $('storyEndings').replaceChildren();for(const [id,e]of Object.entries(ENDINGS)){const span=document.createElement('span');span.className=this.storyEnds.includes(id)?'found':'';span.textContent=this.storyEnds.includes(id)?'✦ '+e.title:'◇ UNDISCOVERED ENDING';$('storyEndings').append(span);}$('storyReset').textContent=s.ending?'PLAY ANOTHER NIGHT ↗':'NEW EPISODE';$('storyHint').disabled=!!s.ending;
 }
}
